import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'

import { ActionsById } from 'scenes/insights/utils/resultSeries'
import { isAuthenticatedTeam, teamLogic } from 'scenes/teamLogic'

import type { ActionType, TeamPublicType, TeamType } from '~/types'

import { actionsRetrieve } from 'products/actions/frontend/generated/api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface actionNamesModelValues {
    currentProjectId: number | string // teamLogic
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    actionsById: ActionsById
    requestedActionIds: number[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface actionNamesModelActions {
    loadActionNames: (ids: number[]) => {
        ids: number[]
    }
    requestActionNames: (ids: number[]) => {
        ids: number[]
    }
    setActionNames: (actionsById: ActionsById) => {
        actionsById: Partial<Record<number | string, Pick<ActionType, 'name'>>>
    }
}

export type actionNamesModelType = MakeLogicType<actionNamesModelValues, actionNamesModelActions>

export const actionNamesModel = kea<actionNamesModelType>([
    path(['models', 'actionNamesModel']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentProjectId']],
    })),
    actions({
        loadActionNames: (ids: number[]) => ({ ids }),
        requestActionNames: (ids: number[]) => ({ ids }),
        setActionNames: (actionsById: ActionsById) => ({ actionsById }),
    }),
    reducers({
        requestedActionIds: [
            [] as number[],
            {
                requestActionNames: (state, { ids }) => [...state, ...ids],
            },
        ],
        actionsById: [
            {} as ActionsById,
            {
                setActionNames: (state, { actionsById }) => ({ ...state, ...actionsById }),
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        loadActionNames: ({ ids }) => {
            const newIds = [...new Set(ids)].filter((id) => !values.requestedActionIds.includes(id))
            // A shared or exported view has no session that can read actions
            if (newIds.length > 0 && isAuthenticatedTeam(values.currentTeam)) {
                actions.requestActionNames(newIds)
            }
        },
        requestActionNames: async ({ ids }) => {
            // Retrieve, unlike list, also returns a soft-deleted action, which a saved query can still reference
            const entries = await Promise.all(
                ids.map(async (id) => {
                    try {
                        const action = await actionsRetrieve(String(values.currentProjectId), id)
                        return [id, { name: action.name ?? null }] as const
                    } catch {
                        return [id, { name: null }] as const
                    }
                })
            )
            actions.setActionNames(Object.fromEntries(entries))
        },
    })),
])
